INSERT INTO products (id, category_id, name, price, description, material, dimensions, usage, care, featured, is_new) VALUES
  (1, 0, 'کیف دوشی زیتون', 485000, 'یک همراه پارچه‌ای برای کتاب، دفتر و خرده‌ریزهای روزانه. دوخت‌های عمودی و دسته‌های روشن، ظاهر سادهٔ این کیف را کامل می‌کنند.', 'کتان پنبه‌ای با دوخت عمودی', '۳۵ × ۳۰ × ۱۰ سانتی‌متر', 'حمل کتاب و وسایل روزانه', 'شست‌وشوی ملایم با آب سرد و شویندهٔ رقیق، خشک‌کردن در سایه. دستور قطعی پس از تأیید پارچه اعلام می‌شود.', true, false),
  (2, 1, 'ست آشپزخانه چهارخونه', 325000, 'ترکیب چهارخانه‌های آرام و لبه‌دوزی زیتونی برای گوشهٔ آشپزخانه. این ست نمونه شامل دستکش پارچه‌ای و دستگیره است؛ مشخصات مقاومت حرارتی هنوز تأیید نشده است.', 'پنبهٔ چهارخانه با لایهٔ میانی پارچه‌ای', 'دستکش ۲۸ × ۱۷؛ دستگیره ۲۰ × ۲۰ سانتی‌متر', 'همراهی دکور آشپزخانه؛ مقاومت حرارتی تأیید نشده است', 'شست‌وشوی ملایم با آب سرد و شویندهٔ رقیق، خشک‌کردن در سایه. دستور قطعی پس از تأیید پارچه اعلام می‌شود.', true, true),
  (3, 2, 'جامدادی دارچین', 185000, 'جایی جمع‌وجور برای مدادها و ایده‌های کوچک. فرم ساده، زیپ سرتاسری و رنگ گرم دارچینی، آن را به همراهی برای میز کار تبدیل می‌کند.', 'کتان با آستر پنبه‌ای', '۲۱ × ۸ × ۶ سانتی‌متر', 'نگهداری مداد و لوازم تحریر', 'شست‌وشوی ملایم با آب سرد و شویندهٔ رقیق، خشک‌کردن در سایه. دستور قطعی پس از تأیید پارچه اعلام می‌شود.', true, true),
  (4, 3, 'جا قمقمه‌ای چهارخونه', 265000, 'برای وقتی که قمقمه هم با تو راهی می‌شود. یک کاور پارچه‌ای با بند بلند و طرح چهارخانه؛ قمقمهٔ داخل تصویر صرفاً برای نمایش کاربرد است.', 'پنبهٔ چهارخانه با بند پارچه‌ای', 'ارتفاع ۲۳؛ قطر ۸ سانتی‌متر', 'حمل قمقمه؛ قمقمه در محصول نمونه لحاظ نشده', 'شست‌وشوی ملایم با آب سرد و شویندهٔ رقیق، خشک‌کردن در سایه. دستور قطعی پس از تأیید پارچه اعلام می‌شود.', false, true),
  (5, 4, 'جا سیخی سفر', 295000, 'یک نظم‌دهندهٔ رول‌شونده برای وسایل پیک‌نیک. پارچهٔ خاکی و بند گره‌ای، فرم ساده و جمع‌شوندهٔ آن را شکل می‌دهند؛ سیخ همراه محصول نیست.', 'برزنت پنبه‌ای', '۶۰ × ۳۵ سانتی‌متر در حالت باز', 'نظم‌دهی سیخ‌های سرد و تمیز؛ سیخ همراه نیست', 'شست‌وشوی ملایم با آب سرد و شویندهٔ رقیق، خشک‌کردن در سایه. دستور قطعی پس از تأیید پارچه اعلام می‌شود.', false, false),
  (6, 5, 'کیف لپ‌تاپ ابر', 545000, 'دوخت‌های موج‌دار، رنگ روشن و فرم پاکتی؛ همراه پارچه‌ای میز کار تو. اندازه و سازگاری با مدل‌های لپ‌تاپ باید پیش از فروش واقعی تکمیل شود.', 'کتان پنبه‌ای با دوخت لحافی', '۳۴ × ۲۵ سانتی‌متر', 'حمل لپ‌تاپ؛ سازگاری ابعاد باید پیش از خرید تأیید شود', 'شست‌وشوی ملایم با آب سرد و شویندهٔ رقیق، خشک‌کردن در سایه. دستور قطعی پس از تأیید پارچه اعلام می‌شود.', true, false),
  (7, 6, 'پیش‌بند باغچه', 395000, 'برای آشپزی، رنگ‌زدن و ساختن چیزهای تازه. یک پیش‌بند زیتونی با جیب روشن برای ابزارهایی که دوست داری دم دست باشند.', 'لینن پنبه‌ای', '۷۵ × ۶۰ سانتی‌متر', 'نقاشی و آشپزی روزانه', 'شست‌وشوی ملایم با آب سرد و شویندهٔ رقیق، خشک‌کردن در سایه. دستور قطعی پس از تأیید پارچه اعلام می‌شود.', false, true),
  (8, 0, 'کیف گل‌های ریز', 465000, 'گل‌های کوچک روی زمینهٔ روشن؛ یک کیف پارچه‌ای برای روزهای سبک و قدم‌های بی‌عجله. دسته‌های هم‌طرح، قصهٔ گل‌ها را ادامه می‌دهند.', 'پنبهٔ چاپ‌دار با آستر ساده', '۳۲ × ۲۸ × ۹ سانتی‌متر', 'حمل وسایل سبک روزمره', 'شست‌وشوی ملایم با آب سرد و شویندهٔ رقیق، خشک‌کردن در سایه. دستور قطعی پس از تأیید پارچه اعلام می‌شود.', false, true);
